-- Draft revision snapshots: immutable history generated by a private trigger.
-- Production requires an independently reviewed migration.
create table if not exists public.commercial_quotation_draft_revisions (
  id uuid primary key default gen_random_uuid(),
  draft_id uuid not null references public.commercial_quotation_drafts(id) on delete restrict,
  org_id uuid not null references public.organizations(id),
  owner_profile_id uuid not null references public.profiles(id),
  editor_profile_id uuid not null references public.profiles(id),
  revision bigint not null check (revision > 0),
  status text not null check (status in ('active','deleted','archived')),
  snapshot jsonb not null check (jsonb_typeof(snapshot)='object'),
  recorded_at timestamptz not null default now(),
  unique(draft_id, revision)
);
create index if not exists commercial_draft_revisions_recent
 on public.commercial_quotation_draft_revisions (org_id,draft_id,revision desc);
alter table public.commercial_quotation_draft_revisions enable row level security;
revoke all on public.commercial_quotation_draft_revisions from anon,authenticated;
grant select on public.commercial_quotation_draft_revisions to authenticated;
create policy commercial_draft_revisions_read on public.commercial_quotation_draft_revisions
 for select to authenticated using (
   exists(select 1 from public.profiles p
     where p.user_id=(select auth.uid())
     and p.org_id=commercial_quotation_draft_revisions.org_id
     and p.is_active
     and (p.id=commercial_quotation_draft_revisions.owner_profile_id
       or p.role in ('admin','manager')))
 );
create schema if not exists private;
revoke all on schema private from public,anon,authenticated;
-- Private trigger function can insert append-only revision records.
create or replace function private.record_commercial_draft_revision()
returns trigger language plpgsql security definer
set search_path=pg_catalog,public
as $audit$
begin
  if TG_OP='UPDATE' then
    if old.org_id<>new.org_id or old.owner_profile_id<>new.owner_profile_id or old.id<>new.id
      or new.revision<>old.revision+1 or new.updated_at<=old.updated_at
      or old.status<>'active' then
      raise exception 'Invalid quotation draft revision/owner transition';
    end if;
  elsif TG_OP='INSERT' and (new.revision<>1 or new.status<>'active') then
    raise exception 'Invalid initial quotation draft revision';
  end if;
  insert into public.commercial_quotation_draft_revisions
    (draft_id,org_id,owner_profile_id,editor_profile_id,revision,status,snapshot)
  values
    (new.id,new.org_id,new.owner_profile_id,new.updated_by_profile_id,
     new.revision,new.status,new.draft_json);
  return new;
end;
$audit$;
revoke all on function private.record_commercial_draft_revision() from public,anon,authenticated;
create trigger record_commercial_draft_revision
 after insert or update on public.commercial_quotation_drafts
 for each row execute function private.record_commercial_draft_revision();
